    #[test]
    fn test_execute_const() {
        let mut ctx = VmContext::default();
        let mut vm = Vm::new(&mut ctx);

        let program = make_program(vec![Instruction::PushConst(42.0)]);
        let result = vm.execute(&program).unwrap();

        assert!((result - 42.0).abs() < 1e-10);
    }

